const express = require('express');
const app = express();
const path = require('path');

// Search indexing service configuration
const ALLOWED_TAGS = ['mark', 'em', 'strong', 'b', 'i'];

const config = {
  serviceName: 'SearchIndex',
  renderMode: process.env.RENDER_MODE || 'server',
  templateEngine: process.env.TEMPLATE_ENGINE || 'ejs',
  sanitizeLevel: parseInt(process.env.SANITIZE_LEVEL || '2'),
  maxResults: parseInt(process.env.MAX_RESULTS || '50'),
  highlightTag: ALLOWED_TAGS.includes(process.env.HIGHLIGHT_TAG) ? process.env.HIGHLIGHT_TAG : 'mark'
};

// In-memory search index
const searchIndex = new Map();

// Index document
function indexDocument(id, content, metadata) {
  const tokens = content.toLowerCase().split(/\s+/);
  const entry = { id, content, metadata, tokens, indexedAt: Date.now() };
  searchIndex.set(id, entry);
  return entry;
}

// Search function
function search(query, limit) {
  const queryTokens = query.toLowerCase().split(/\s+/);
  const results = [];
  for (const [id, entry] of searchIndex) {
    const score = queryTokens.reduce((acc, qt) => {
      return acc + entry.tokens.filter(t => t.includes(qt)).length;
    }, 0);
    if (score > 0) results.push({ ...entry, score });
  }
  results.sort((a, b) => b.score - a.score);
  return results.slice(0, limit || config.maxResults);
}

// Highlight matching terms in content
function highlightMatches(content, query, tag) {
  const terms = query.split(/\s+/);
  let highlighted = content;
  terms.forEach(term => {
    const regex = new RegExp(`(${escapeRegex(term)})`, 'gi');
    highlighted = highlighted.replace(regex, `<${tag}>$1</${tag}>`);
  });
  return highlighted;
}

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Content sanitizer - multi-level
class ContentSanitizer {
  constructor(level) {
    this.level = level;
  }

  sanitize(input) {
    if (this.level >= 3) {
      return this.strictSanitize(input);
    } else if (this.level >= 2) {
      return this.moderateSanitize(input);
    } else {
      return this.lightSanitize(input);
    }
  }

  strictSanitize(input) {
    return input.replace(/[<>&"']/g, (ch) => {
      const map = { '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#x27;' };
      return map[ch];
    });
  }

  moderateSanitize(input) {
    // Allow configured highlight tags through
    const allowedTag = config.highlightTag;
    const preserved = [];
    let counter = 0;

    // Preserve allowed tags
    const tagPattern = new RegExp(`</?${escapeRegex(allowedTag)}>`, 'gi');
    let processed = input.replace(tagPattern, (match) => {
      const placeholder = `__PRESERVED_${counter}__`;
      preserved.push({ placeholder, value: match });
      counter++;
      return placeholder;
    });

    // Sanitize everything else
    processed = this.strictSanitize(processed);

    // Restore preserved tags
    preserved.forEach(({ placeholder, value }) => {
      processed = processed.replace(placeholder, value);
    });

    return processed;
  }

  lightSanitize(input) {
    // Fully HTML-escape input. A regex-based blocklist that only strips
    // <script> tags is not a safe sanitizer, so escape all HTML-significant
    // characters instead.
    return this.strictSanitize(input);
  }
}

const sanitizer = new ContentSanitizer(config.sanitizeLevel);

// API Routes
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.post('/api/index', (req, res) => {
  const { id, content, metadata } = req.body;
  if (!id || !content) return res.status(400).json({ error: 'id and content required' });
  const entry = indexDocument(id, content, metadata || {});
  res.json({ success: true, indexed: entry.id });
});

app.get('/api/search', (req, res) => {
  const { q, limit, format } = req.query;
  if (!q) return res.status(400).json({ error: 'query parameter q required' });

  const results = search(q, parseInt(limit) || config.maxResults);

  if (format === 'html') {
    const htmlResults = results.map(r => {
      const highlighted = highlightMatches(r.content, q, config.highlightTag);
      return sanitizer.sanitize(highlighted);
    });
    res.send(renderSearchPage(q, htmlResults));
  } else {
    res.json({ query: q, results: results.map(r => ({ id: r.id, content: r.content, score: r.score })) });
  }
});

function renderSearchPage(query, htmlResults) {
  const sanitizedQuery = sanitizer.sanitize(query);
  return `<!DOCTYPE html>
<html>
<head><title>Search Results - ${config.serviceName}</title></head>
<body>
  <h1>Results for: ${sanitizedQuery}</h1>
  <div class="results">
    ${htmlResults.map((r, i) => `<div class="result" id="r${i}">${r}</div>`).join('\n    ')}
  </div>
</body>
</html>`;
}

// Seed some documents
indexDocument('doc1', 'Introduction to search indexing and information retrieval', { author: 'admin' });
indexDocument('doc2', 'Advanced techniques for full-text search optimization', { author: 'admin' });
indexDocument('doc3', 'Building scalable search infrastructure with Node.js', { author: 'dev' });

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Search service running on port ${PORT}`));

module.exports = app;
